F=/scratch/jjyeung/orch_n30/fb_pack
mkdir -p $F/camformrev/work; cp $F/donorrev/AGENTS.md $F/camformrev/AGENTS.md; echo  | base64 -d > $F/camformrev/PROMPT.md; sha256sum $F/camformrev/PROMPT.md | cut -c1-12; cat $F/camform/out/fbp_camform.tar.sha256; cat $F/camform/out/FILES_TOUCHED.json | head -c 800; echo
cd $F/camformrev && tmux new-session -d -s fbp_camformrev "OMP_NUM_THREADS=8 MKL_NUM_THREADS=8 OPENBLAS_NUM_THREADS=8 nice -n 10 timeout 7200 agent -p -f --sandbox disabled --trust --model claude-opus-5-5-xhigh 'Read PROMPT.md in this folder and carry out the task it describes. Write only in this folder.' > $F/camformrev/cursor.log 2>&1" </dev/null >/dev/null 2>&1
sleep 3; tmux ls | grep fbp | cut -c1-24; date -u +%TZ
